      --accent-navy: #1e3a5f;
      --accent-gold: #c9a84c;
      --accent-rust: #9a3412;
      --accent-sage: #4d7c5f;
      --accent-plum: #6b4c6e;
      --accent-teal: #0f766e;
      --accent-amber: #b45309;
      --accent-slate: #475569;
      --font-body: 'Source Sans 3', system-ui, sans-serif;
      --font-heading: 'Crimson Pro', Georgia, serif;
      --font-mono: 'Source Sans Mono', monospace;
    }

    * { box-sizing: border-box; margin: 0; padding: 0; }

    body {
      font-family: var(--font-body);
      background: var(--bg);
      color: var(--text);
      min-height: 100vh;
      padding: 48px 24px;
    }

    .container {
      max-width: 1100px;
      margin: 0 auto;
    }

    header {
      margin-bottom: 40px;
      padding-bottom: 32px;
      border-bottom: 1px solid var(--border);
    }

    h1 {
      font-family: var(--font-heading);
      font-size: 2.2rem;
      font-weight: 600;
      color: var(--accent-navy);
      line-height: 1.2;
      margin-bottom: 8px;
    }

    .subtitle {
      font-size: 1rem;
      color: var(--text-dim);
      line-height: 1.5;
    }

    .chart-wrapper {
      background: var(--surface);
