      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 20px;
    }

    .insight-card h3 {
      font-family: var(--font-heading);
      font-size: 1.05rem;
      font-weight: 600;
      color: var(--accent-navy);
      margin-bottom: 6px;
    }

    .insight-card p {
      font-size: 0.85rem;
      color: var(--text-dim);
      line-height: 1.5;
    }

    .insight-card .metric {
      font-family: var(--font-mono);
      font-size: 1.4rem;
      font-weight: 600;
      color: var(--accent-rust);
      margin-top: 8px;
    }

    .legend-panel {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 20px 24px;
    }

    .legend-panel h3 {
      font-family: var(--font-heading);
      font-size: 1rem;
      font-weight: 600;
      color: var(--accent-navy);
      margin-bottom: 16px;
    }

    .legend-items {
      display: flex;
      flex-wrap: wrap;
      gap: 16px 32px;
    }

    .legend-item {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 0.85rem;
    }

    .legend-dot {
      width: 10px;
      height: 10px;
      border-radius: 50%;
    }

    .legend-line {
      width: 20px;
      height: 2px;
    }

    .note {
      margin-top: 24px;
      padding-top: 20px;
      border-top: 1px solid var(--border);
