    @media (prefers-color-scheme: dark) {
      :root {
        --bg: #0f1117;
        --surface: #1a1d24;
        --border: rgba(255,255,255,0.07);
        --text: #e8e4df;
        --text-dim: #8b9098;
      }
    }
  </style>
</head>
<body>
  <div class="container">
    <header>
      <h1>Health Investment & Maternal Mortality Trajectories</h1>
      <p class="subtitle">How changes in health expenditure correspond to changes in mortality across eight countries, 2005–2021</p>
    </header>

    <div class="chart-wrapper">
      <div class="chart-container">
        <canvas id="mainChart"></canvas>
      </div>
    </div>

    <div class="insight-grid">
      <div class="insight-card">
        <h3>Top Improver</h3>
        <p>Ethiopia reduced MMR by 69% (871 → 267) while increasing health spend</p>
        <div class="metric">−69% MMR</div>
      </div>
      <div class="insight-card">
        <h3>Rural–Urban Gap</h3>
        <p>Nigeria shows the largest disparity: rural MMR is 2.5× the urban rate</p>
        <div class="metric">860 vs 350</div>
      </div>
      <div class="insight-card">
        <h3>Midwife Coverage Leaders</h3>
        <p>Rwanda & Peru achieved 90%+ skilled birth attendance with sustained spending</p>
        <div class="metric">91–95%</div>
      </div>
    </div>

    <div class="legend-panel">
      <h3>Countries & Trajectory Arrows (2005 → 2021)</h3>
      <div class="legend-items">
        <div class="legend-item"><div class="legend-dot" style="background:#9a3412"></div>Ethiopia</div>
        <div class="legend-item"><div class="legend-dot" style="background:#1e3a5f"></div>India</div>
        <div class="legend-item"><div class="legend-dot" style="background:#4d7c5f"></div>Rwanda</div>
        <div class="legend-item"><div class="legend-dot" style="background:#6b4c6e"></div>Bangladesh</div>
        <div class="legend-item"><div class="legend-dot" style="background:#b45309"></div>Nigeria</div>
        <div class="legend-item"><div class="legend-dot" style="background:#0f766e"></div>Cambodia</div>
        <div class="legend-item"><div class="legend-dot" style="background:#c9a84c"></div>Peru</div>
        <div class="legend-item"><div class="legend-dot" style="background:#475569"></div>Nepal</div>
        <div class="legend-item"><div class="legend-line" style="background:#9a3412;opacity:0.5"></div>Trajectory</div>
      </div>
      <p class="note">Each point represents a country-year observation. Arrows show direction of change from 2005 to 2021. Point labels show the year (5=2005, 9=2009, 13=2013, 17=2017, 21=2021). Bubble size proportional to MMR magnitude.</p>
    </div>
  </div>

  <script>
    const isDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

    const textColor = isDark ? '#c8c4be' : '#6b7280';
    const gridColor = isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.06)';
    const surfaceColor = isDark ? 'rgba(255,255,255,0.03)' : 'rgba(0,0,0,0.02)';

    const colors = {
      Ethiopia: '#9a3412',
      India: '#1e3a5f',
      Rwanda: '#4d7c5f',
      Bangladesh: '#6b4c6e',
      Nigeria: '#b45309',
      Cambodia: '#0f766e',
      Peru: '#c9a84c',
      Nepal: '#475569'
    };

    const mmrData = [
      {country:"Ethiopia",year:2005,mmr:871,health_exp_pct_gdp:3.5},
      {country:"Ethiopia",year:2009,mmr:676,health_exp_pct_gdp:4.0},
      {country:"Ethiopia",year:2013,mmr:497,health_exp_pct_gdp:4.7},
      {country:"Ethiopia",year:2017,mmr:401,health_exp_pct_gdp:3.9},
      {country:"Ethiopia",year:2021,mmr:267,health_exp_pct_gdp:3.6},
      {country:"India",year:2005,mmr:280,health_exp_pct_gdp:4.0},
      {country:"India",year:2009,mmr:212,health_exp_pct_gdp:3.9},
      {country:"India",year:2013,mmr:167,health_exp_pct_gdp:3.8},
      {country:"India",year:2017,mmr:133,health_exp_pct_gdp:3.5},
      {country:"India",year:2021,mmr:97,health_exp_pct_gdp:3.3},
      {country:"Rwanda",year:2005,mmr:720,health_exp_pct_gdp:6.6},
      {country:"Rwanda",year:2009,mmr:487,health_exp_pct_gdp:8.2},
      {country:"Rwanda",year:2013,mmr:320,health_exp_pct_gdp:7.5},
      {country:"Rwanda",year:2017,mmr:248,health_exp_pct_gdp:6.8},
      {country:"Rwanda",year:2021,mmr:203,health_exp_pct_gdp:7.1},
      {country:"Bangladesh",year:2005,mmr:322,health_exp_pct_gdp:2.6},
      {country:"Bangladesh",year:2009,mmr:272,health_exp_pct_gdp:2.8},
      {country:"Bangladesh",year:2013,mmr:209,health_exp_pct_gdp:2.8},
      {country:"Bangladesh",year:2017,mmr:173,health_exp_pct_gdp:2.4},
      {country:"Bangladesh",year:2021,mmr:123,health_exp_pct_gdp:2.6},
      {country:"Nigeria",year:2005,mmr:946,health_exp_pct_gdp:3.4},
      {country:"Nigeria",year:2009,mmr:867,health_exp_pct_gdp:3.3},
      {country:"Nigeria",year:2013,mmr:814,health_exp_pct_gdp:3.4},
      {country:"Nigeria",year:2017,mmr:780,health_exp_pct_gdp:3.6},
      {country:"Nigeria",year:2021,mmr:621,health_exp_pct_gdp:3.4},
      {country:"Cambodia",year:2005,mmr:472,health_exp_pct_gdp:5.7},
      {country:"Cambodia",year:2009,mmr:290,health_exp_pct_gdp:6.1},
      {country:"Cambodia",year:2013,mmr:170,health_exp_pct_gdp:6.0},
      {country:"Cambodia",year:2017,mmr:141,health_exp_pct_gdp:6.1},
      {country:"Cambodia",year:2021,mmr:218,health_exp_pct_gdp:7.5},
      {country:"Peru",year:2005,mmr:129,health_exp_pct_gdp:4.5},
      {country:"Peru",year:2009,mmr:103,health_exp_pct_gdp:5.0},
      {country:"Peru",year:2013,mmr:89,health_exp_pct_gdp:5.3},
      {country:"Peru",year:2017,mmr:75,health_exp_pct_gdp:5.2},
      {country:"Peru",year:2021,mmr:69,health_exp_pct_gdp:6.3},
      {country:"Nepal",year:2005,mmr:543,health_exp_pct_gdp:5.1},
      {country:"Nepal",year:2009,mmr:380,health_exp_pct_gdp:5.5},
      {country:"Nepal",year:2013,mmr:258,health_exp_pct_gdp:5.8},
      {country:"Nepal",year:2017,mmr:186,health_exp_pct_gdp:5.6},
      {country:"Nepal",year:2021,mmr:151,health_exp_pct_gdp:5.2}
    ];

    const countries = ['Ethiopia','India','Rwanda','Bangladesh','Nigeria','Cambodia','Peru','Nepal'];
    const yearLabel = {2005:'5',2009:'9',2013:'13',2017:'17',2021:'21'};

    const datasets = [];

    countries.forEach(country => {
      const countryPoints = mmrData.filter(d => d.country === country);
      const sorted = countryPoints.sort((a,b) => a.year - b.year);

      const scatterPoints = sorted.map(p => ({
        x: p.health_exp_pct_gdp,
        y: p.mmr
      }));

      datasets.push({
        label: country,
        data: scatterPoints,
        borderColor: colors[country],
        backgroundColor: colors[country] + 'cc',
        pointRadius: sorted.map(p => Math.max(4, Math.min(14, p.mmr / 80))),
        pointHoverRadius: sorted.map(p => Math.max(6, Math.min(18, p.mmr / 80))) ,
        borderWidth: 2,
        showLine: false,
        pointLabel: sorted.map(p => yearLabel[p.year])
      });
    });

    const countriesInit = countries.map(c => mmrData.find(d => d.country === c && d.year === 2005));
    const countriesFinal = countries.map(c => mmrData.find(d => d.country === c && d.year === 2021));

    countries.forEach((country, i) => {
      datasets.push({
        label: country + ' trajectory',
        data: [
          {x: countriesInit[i].health_exp_pct_gdp, y: countriesInit[i].mmr},
          {x: countriesFinal[i].health_exp_pct_gdp, y: countriesFinal[i].mmr}
        ],
        borderColor: colors[country] + '88',
        backgroundColor: 'transparent',
        borderWidth: 2,
        borderDash: [4, 3],
        showLine: true,
        pointRadius: 0,
        pointHoverRadius: 0,
        tension: 0
      });
    });

    const config = {
      type: 'scatter',
      data: { datasets },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { display: false },
          tooltip: {
            backgroundColor: isDark ? '#1a1d24' : '#ffffff',
            titleColor: isDark ? '#e8e4df' : '#1c1917',
            bodyColor: isDark ? '#c8c4be' : '#6b7280',
            borderColor: isDark ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.08)',
            borderWidth: 1,
            padding: 12,
            titleFont: { family: "'Source Sans 3', sans-serif", size: 13, weight: '600' },
            bodyFont: { family: "'Source Sans 3', sans-serif", size: 12 },
            callbacks: {
              label: function(ctx) {
                if (ctx.dataset.label.includes('trajectory')) return null;
                const pt = mmrData.find(d =>
                  d.country === ctx.dataset.label &&
                  d.health_exp_pct_gdp === ctx.parsed.x &&
                  d.mmr === ctx.parsed.y
                );
                if (!pt) return null;
                return [
                  `${pt.country}, ${pt.year}`,
                  `Health spend: ${pt.health_exp_pct_gdp}% GDP`,
                  `Maternal mortality: ${pt.mmr} per 100k`
                ];
              }
            },
            filter: function(ctx) {
              return !ctx.dataset.label.includes('trajectory');
            }
          }
        },
        scales: {
          x: {
            title: {
              display: true,
              text: 'Health Expenditure (% of GDP)',
              font: { family: "'Source Sans 3', sans-serif", size: 13, weight: '500' },
